/** Exercises the actual metadata adapter, without a registry/provider or a new parsing path. */
class VettingPackageIdentityContextTest {
    static final class Fixture {
        final SourceDocument source=new SourceDocument();final DocumentBlock original=new DocumentBlock();final VettingCorpus.Part part=new VettingCorpus.Part();final VettingCorpus.Chunk chunk=new VettingCorpus.Chunk();final ObjectNode rawPart=JsonUtils.mapper().createObjectNode();
        final String sha=String.join("",Collections.nCopies(64,"a")),partSha=String.join("",Collections.nCopies(64,"b"));
        final String root="/{urn:word}ftr[1]",node=root+"/{urn:word}p[1]";
        Fixture(){source.setId(42L);source.setProjectId("project");source.setCategory(SourceDocument.CATEGORY_VETTING_PACKAGE);source.setReviewRole("tender");source.setDocumentScope("package");source.setParseStatus("PARSED");source.setSourceSha256(sha);source.setFileName("opaque-name.docx");original.setId("opaque-id");original.setLocation("opaque-anchor");original.setKind("paragraph");original.setText("Contract No: PKG-1");original.setOriginalText(original.getText());
            ObjectNode position=JsonUtils.mapper().createObjectNode();position.put("kind","docx_native");position.put("sourceSha256",sha);position.put("partName","word/opaque.xml");position.put("partSha256",partSha);position.put("nodePath",node);original.setSourcePosition(position);
            ObjectNode context=JsonUtils.mapper().createObjectNode();context.putObject("nativeDocxSection").put("sectionId","retained-section");original.setReadingContext(context);refresh();
            ObjectNode coverage=JsonUtils.mapper().createObjectNode(),inventory=coverage.putObject("nativeDocxTables");inventory.put("sourceSha256",sha);ObjectNode inventoryPart=inventory.withArray("parts").addObject();inventoryPart.put("partName","word/opaque.xml");inventoryPart.put("partSha256",partSha);ObjectNode loaded=inventoryPart.withArray("loadedRoots").addObject();loaded.put("kind","footer");loaded.put("nodePath",root);
            coverage.with("nativeDocxSections").putObject("sourcePosition").put("sourceSha256",sha);
            for(String id:Arrays.asList("section1","section2")){ObjectNode section=coverage.with("nativeDocxSections").withArray("sections").addObject();section.put("sectionId",id);ObjectNode binding=section.withArray("headerFooterBindings").addObject();binding.put("status","section1".equals(id)?"explicit_target_loaded":"inherited_target_candidate");binding.put("kind","footer");binding.put("variant","default");binding.put("effectiveState","unknown");ObjectNode target=binding.putObject("targetPart");target.put("partName","word/opaque.xml");target.put("partSha256",partSha);target.put("rootNodePath",root);target.put("rootQName","{urn:word}ftr");}
            source.setParseCoverageJson(JsonUtils.write(coverage));
        }
        void refresh(){source.setStructuredContentJson(JsonUtils.write(Collections.singletonList(original)));source.setTextContent(original.getText());part.setBlockId(original.getId());part.setAnchor(original.getLocation());part.setText(original.getText());part.setStartOffset(0);part.setEndOffset(original.getText().length());part.setSourcePosition(original.getSourcePosition().deepCopy());rawPart.put("blockId",part.getBlockId());rawPart.put("anchor",part.getAnchor());rawPart.put("text",part.getText());rawPart.put("startOffset",0);rawPart.put("endOffset",part.getEndOffset());rawPart.set("sourcePosition",original.getSourcePosition().deepCopy());ObjectNode payload=JsonUtils.mapper().createObjectNode();payload.withArray("parts").add(rawPart);chunk.setCanonicalPayload(payload);chunk.setDocumentId("42");EvidencePointer pointer=new EvidencePointer();pointer.setJavaParsedSourceHash(VettingCorpus.sourceHash(source));pointer.setOriginalSourceSha256(sha);chunk.setCanonicalEvidence(pointer);}
        DocumentBlock bound(){DocumentBlock b=new DocumentBlock();b.setId(part.getBlockId());b.setLocation(part.getAnchor());b.setText(part.getText());b.setOriginalText(part.getText());OerBusinessEvidence.bindRuleContext("project",source,chunk,part,b);return b;}
        void select(int start,int end){String selected=original.getText().substring(start,end);part.setStartOffset(start);part.setEndOffset(end);part.setText(selected);rawPart.put("startOffset",start);rawPart.put("endOffset",end);rawPart.put("text",selected);}
    }
    private JsonNode context(DocumentBlock block){return block.getReadingContext().path(VettingPackageIdentity.CONTEXT);}
    @Test void exactUniqueNativeBindingRetainsTypedFooterAndAllInheritedRelationsWithoutPages(){Fixture f=new Fixture();DocumentBlock b=f.bound();assertEquals("source_bound",context(b).path("status").asText());assertEquals("paragraph",b.getKind());assertEquals(f.original.getSourcePosition(),b.getSourcePosition());assertEquals("footer",context(b).path("storyKind").asText());assertEquals(2,context(b).path("sectionRelations").size());assertNull(b.getPageNo());assertEquals("unknown",context(b).path("physicalWordPageStatus").asText());assertEquals("captured_identity_only",context(b).path("originalBytesStatus").asText());assertEquals("retained-section",b.getReadingContext().path("nativeDocxSection").path("sectionId").asText());}
    @Test void partialAcceptedRangeKeepsOnlyItsTextAndDoesNotCopyFullCellsOrFields(){Fixture f=new Fixture();f.original.getCells().add("UNSELECTED SECRET CELL");ObjectNode field=JsonUtils.mapper().createObjectNode();field.put("fieldValue","UNSELECTED FIELD");f.original.getWordFields().add(field);f.refresh();int start=f.original.getText().indexOf("PKG");f.part.setStartOffset(start);f.part.setText("PKG-1");f.rawPart.put("startOffset",start);f.rawPart.put("text","PKG-1");DocumentBlock b=f.bound();assertEquals("source_bound",context(b).path("status").asText());assertEquals("PKG-1",b.getText());assertTrue(b.getCells().isEmpty());assertTrue(b.getWordFields().isEmpty());assertFalse(context(b).path("completeOriginalBlock").asBoolean());VettingPackageIdentity.Review review=VettingPackageIdentity.review(Collections.singletonList(new VettingRuleEngine.Source("42","NTT","source",VettingCorpus.sourceHash(f.source),Collections.singletonList(b),b.getText())),null);assertTrue(review.outputs().isEmpty());assertEquals("unknown_no_own_declaration",review.ledger().path("fields").path("number").path("status").asText());}
    @Test void duplicateBlockIdsCannotProvideAStoryOrOwnIdentity(){Fixture f=new Fixture();f.source.setStructuredContentJson(JsonUtils.write(Arrays.asList(f.original,f.original)));f.chunk.getCanonicalEvidence().setJavaParsedSourceHash(VettingCorpus.sourceHash(f.source));DocumentBlock b=f.bound();assertEquals("unknown",context(b).path("status").asText());assertEquals("original_block_not_unique",context(b).path("reason").asText());assertNull(b.getSourcePosition());assertNull(b.getKind());}
    @Test void staleSourceHashOriginalIdentityOrProjectCannotProvideCurrentContext(){for(String mutation:Arrays.asList("hash","original","project","parse")){Fixture f=new Fixture();if("hash".equals(mutation))f.source.setTextContent("Changed source");if("original".equals(mutation))f.source.setSourceSha256("changed");if("project".equals(mutation))f.source.setProjectId("other");if("parse".equals(mutation))f.source.setParseStatus("FAILED");DocumentBlock b=f.bound();assertEquals("unknown",context(b).path("status").asText(),mutation);assertNull(b.getSourcePosition(),mutation);}}
    @Test void mismatchedPositionAndAmbiguousAcceptedPartsDoNotReceiveStructure(){for(String mutation:Arrays.asList("position","duplicate","range")){Fixture f=new Fixture();if("position".equals(mutation))((ObjectNode)f.rawPart.path("sourcePosition")).put("nodePath","other");if("duplicate".equals(mutation))((ObjectNode)f.chunk.getCanonicalPayload()).withArray("parts").add(f.rawPart.deepCopy());if("range".equals(mutation))f.part.setText("Changed adopted text");DocumentBlock b=f.bound();assertEquals("unknown",context(b).path("status").asText(),mutation);assertNull(b.getKind(),mutation);}}
    @Test void missingOrDuplicateTypedRootKeepsTextBindingButStoryUnknown(){for(boolean duplicate:Arrays.asList(false,true)){Fixture f=new Fixture();ObjectNode coverage=(ObjectNode)JsonUtils.parse(f.source.getParseCoverageJson());ObjectNode root=(ObjectNode)coverage.path("nativeDocxTables").path("parts").get(0);if(duplicate)root.withArray("loadedRoots").add(root.path("loadedRoots").get(0).deepCopy());else root.remove("loadedRoots");f.source.setParseCoverageJson(JsonUtils.write(coverage));DocumentBlock b=f.bound();assertEquals("source_bound",context(b).path("status").asText());assertEquals("unknown",context(b).path("storyStatus").asText());assertFalse(context(b).has("storyKind"));}}
    @Test void ordinaryAndCanonicalAdaptersKeepTheSameDeclarationAndEvidence(){Fixture f=new Fixture();DocumentBlock canonical=f.bound();VettingRuleEngine.Source accepted=new VettingRuleEngine.Source("42",f.source.getFileKey(),f.source.getFileName(),VettingCorpus.sourceHash(f.source),Collections.singletonList(canonical),canonical.getText());List<VettingRuleEngine.Source> ordinary=OerBusinessEvidence.ordinaryRuleSources("project",Collections.singletonList(f.source));assertEquals(1,ordinary.size());assertEquals(context(canonical),context(ordinary.get(0).getBlocks().get(0)));JsonNode baseline=JsonUtils.parse("{\"core\":{\"fields\":{\"number\":{\"eligible\":true,\"value\":\"PKG-2\"}}}}");VettingPackageIdentity.Review a=VettingPackageIdentity.review(Collections.singletonList(accepted),baseline),b=VettingPackageIdentity.review(ordinary,baseline);assertEquals(a.ledger(),b.ledger());assertEquals(1,a.outputs().size());assertEquals(JsonUtils.write(a.outputs()),JsonUtils.write(b.outputs()));}
    @Test void rejectedOcrCandidatesCannotBecomeOwnIdentityThroughOrdinaryMetadata(){Fixture f=new Fixture();f.original.setSource("ocr_candidate");f.refresh();List<VettingRuleEngine.Source> sources=OerBusinessEvidence.ordinaryRuleSources("project",Collections.singletonList(f.source));assertEquals("unknown",context(sources.get(0).getBlocks().get(0)).path("status").asText());VettingPackageIdentity.Review review=VettingPackageIdentity.review(sources,null);assertEquals("unknown_no_own_declaration",review.ledger().path("fields").path("number").path("status").asText());}
    @Test void partialSelectionCannotDiscardOtherPrefixOrReferenceSuffixAndBecomeComparable(){
        for(boolean prefix:Arrays.asList(true,false)){Fixture f=new Fixture();f.original.setText(prefix?"Other Contract No: OTHER-1":"Contract No: PKG-001 [other contract reference]");f.refresh();f.select(prefix?6:0,prefix?f.original.getText().length():"Contract No: PKG-001".length());DocumentBlock b=f.bound();assertEquals("source_bound",context(b).path("status").asText());assertFalse(context(b).path(prefix?"selectedStartsAtSourceLineBoundary":"selectedEndsAtSourceLineBoundary").asBoolean());VettingPackageIdentity.Review review=review(f,b);assertTrue(review.outputs().isEmpty());JsonNode declaration=review.ledger().path("declarations").get(0);assertEquals("unknown",declaration.path("classification").asText());assertEquals("selected_declaration_line_not_closed",declaration.path("reason").asText());assertEquals(f.part.getText(),declaration.path("quote").asText());}
    }
    @Test void partialSourceTransportDoesNotCopyUnselectedAnchorCandidateOrArbitraryContextText(){
        Fixture f=new Fixture();String neighbour="UNSELECTED NEIGHBOUR LABEL FULL TEXT";f.original.setText("Context before\nContract No: PKG-1\nContext after");ObjectNode reading=(ObjectNode)f.original.getReadingContext();reading.withArray("anchorCandidates").addObject().put("anchorId","other-block").put("text",neighbour).put("status","candidate_not_assigned");reading.withArray("ownerCandidates").addObject().put("text",neighbour);reading.putObject("unrecognisedContext").put("text",neighbour);((ObjectNode)reading.path("nativeDocxSection")).put("text",neighbour);reading.putObject("nativeDocxOutline").put("text",neighbour).putArray("ancestorOrdinals");f.refresh();f.select(f.original.getText().indexOf("Contract"),f.original.getText().indexOf("\nContext after"));DocumentBlock b=f.bound();
        assertEquals("source_bound",context(b).path("status").asText());assertTrue(context(b).path("selectedStartsAtSourceLineBoundary").asBoolean());assertTrue(context(b).path("selectedEndsAtSourceLineBoundary").asBoolean());assertFalse(JsonUtils.write(b.getReadingContext()).contains(neighbour),"Returned Source.block transport must not copy unselected neighbour text");assertFalse(b.getReadingContext().has("anchorCandidates"));assertFalse(b.getReadingContext().has("ownerCandidates"));assertFalse(b.getReadingContext().has("unrecognisedContext"));assertFalse(b.getReadingContext().path("nativeDocxSection").has("text"));assertFalse(b.getReadingContext().path("nativeDocxOutline").has("text"));assertEquals("retained-section",b.getReadingContext().path("nativeDocxSection").path("sectionId").asText());assertEquals(1,review(f,b).outputs().size(),"A complete ordinary label line remains a comparable candidate with unknown own scope");
    }
    private VettingPackageIdentity.Review review(Fixture f,DocumentBlock b){return VettingPackageIdentity.review(Collections.singletonList(new VettingRuleEngine.Source("42","NTT","source",VettingCorpus.sourceHash(f.source),Collections.singletonList(b),b.getText())),JsonUtils.parse("{\"core\":{\"fields\":{\"number\":{\"eligible\":true,\"value\":\"ADOPTED-002\"}}}}"));}
    private Fixture scopeFixture(String headingText){
        Fixture f=new Fixture();String root="/{urn:word}document[1]/{urn:word}body[1]";ObjectNode memberPosition=(ObjectNode)f.original.getSourcePosition();memberPosition.put("partName","word/document.xml");memberPosition.put("nodePath",root+"/{urn:word}p[2]");((ObjectNode)f.original.getReadingContext()).putObject("nativeDocxOutline").putArray("ancestorOrdinals").add(0);f.refresh();
        DocumentBlock heading=new DocumentBlock();heading.setId("explicit-source-heading");heading.setLocation("source-heading");heading.setKind("paragraph");heading.setText(headingText);ObjectNode headingPosition=memberPosition.deepCopy();headingPosition.put("nodePath",root+"/{urn:word}p[1]");heading.setSourcePosition(headingPosition);f.source.setStructuredContentJson(JsonUtils.write(Arrays.asList(heading,f.original)));f.source.setTextContent(headingText+"\n"+f.original.getText());f.chunk.getCanonicalEvidence().setJavaParsedSourceHash(VettingCorpus.sourceHash(f.source));
        ObjectNode coverage=(ObjectNode)JsonUtils.parse(f.source.getParseCoverageJson()),part=(ObjectNode)coverage.path("nativeDocxTables").path("parts").get(0);part.put("partName","word/document.xml");ObjectNode loaded=(ObjectNode)part.path("loadedRoots").get(0);loaded.put("kind","body");loaded.put("nodePath",root);ObjectNode declared=coverage.putObject("nativeDocxOutline").withArray("headings").addObject();declared.put("ordinalZeroBased",0);declared.set("sourcePosition",headingPosition.deepCopy());declared.withArray("retainedBlockIds").add(heading.getId()).add(f.original.getId());ObjectNode observation=declared.putObject("textObservation");observation.put("status","observed_parser_paragraph_channels");observation.put("text",headingText);observation.set("sourcePosition",headingPosition.deepCopy());f.source.setParseCoverageJson(JsonUtils.write(coverage));return f;
    }
    @Test void exactTypedOutlineSampleAndExternalEdgesExcludeWithoutTransportingUnselectedHeadingText(){
        for(String heading:Arrays.asList("Sample","External reference")){Fixture f=scopeFixture(heading);DocumentBlock b=f.bound();JsonNode exclusion=context(b).path("sourceScopeExclusion");assertEquals("bound_native_outline_exclusion",exclusion.path("status").asText());assertEquals(VettingCorpus.hash(heading),exclusion.path("edges").get(0).path("sourceTextSha256").asText());assertEquals("explicit-source-heading",exclusion.path("edges").get(0).path("sourceBlockId").asText());assertEquals("native_outline_ancestor",exclusion.path("edges").get(0).path("relation").asText());assertFalse(JsonUtils.write(b.getReadingContext()).contains("\""+heading+"\""));VettingPackageIdentity.Review review=review(f,b);assertTrue(review.outputs().isEmpty());JsonNode declaration=review.ledger().path("declarations").get(0);assertEquals("Sample".equals(heading)?"template_or_example":"external_reference",declaration.path("classification").asText());assertEquals(f.part.getText(),declaration.path("quote").asText());assertFalse(JsonUtils.write(declaration).contains("\""+heading+"\""));}
    }
    @Test void staleOrUnboundOutlineExclusionCannotBeGuessedFromThePreviousHeading(){
        for(String failure:Arrays.asList("membership","text","position")){Fixture f=scopeFixture("Sample");ObjectNode coverage=(ObjectNode)JsonUtils.parse(f.source.getParseCoverageJson()),heading=(ObjectNode)coverage.path("nativeDocxOutline").path("headings").get(0);if("membership".equals(failure))heading.putArray("retainedBlockIds").add("another-member");if("text".equals(failure))((ObjectNode)heading.path("textObservation")).put("text","Unbound heading text");if("position".equals(failure))((ObjectNode)heading.path("sourcePosition")).put("partSha256","different-part");f.source.setParseCoverageJson(JsonUtils.write(coverage));DocumentBlock b=f.bound();assertEquals("unknown",context(b).path("sourceScopeExclusion").path("status").asText());VettingPackageIdentity.Review review=review(f,b);assertEquals(1,review.outputs().size());assertEquals("identity_candidate",review.ledger().path("declarations").get(0).path("classification").asText());assertEquals("unknown",review.ledger().path("declarations").get(0).path("scopeStatus").asText());}
    }

    @Test void ordinaryMultiplePartsReadDocumentStructureHashAndCoverageOnceWithoutChangingContextBytes(){
        Fixture f=multipleParts();List<DocumentBlock> originals=VettingCorpus.blocks(f.source);List<String> expected=new ArrayList<>();
        for(DocumentBlock original:originals)expected.add(JsonUtils.write(isolatedBinding(f.source,original).getReadingContext()));
        SourceDocument tracked=spy(f.source);List<VettingRuleEngine.Source> sources=OerBusinessEvidence.ordinaryRuleSources("project",Collections.singletonList(tracked));
        assertEquals(1,sources.size());assertEquals(originals.size(),sources.get(0).getBlocks().size());
        for(int i=0;i<originals.size();i++)assertEquals(expected.get(i),JsonUtils.write(sources.get(0).getBlocks().get(i).getReadingContext()));
        verify(tracked,never()).getTextContent();verify(tracked,times(2)).getStructuredContentJson();verify(tracked,times(1)).getParseCoverageJson();
        for(DocumentBlock block:sources.get(0).getBlocks())assertEquals("source_bound",context(block).path("status").asText());
        assertEquals("bound_native_outline_exclusion",context(sources.get(0).getBlocks().get(1)).path("sourceScopeExclusion").path("status").asText());
    }
    @Test void malformedCoverageIsReadOnceAndKeepsTextBindingsWithUnknownStoryAndScope(){
        Fixture f=multipleParts();f.source.setParseCoverageJson("{broken");SourceDocument tracked=spy(f.source);
        List<VettingRuleEngine.Source> sources=OerBusinessEvidence.ordinaryRuleSources("project",Collections.singletonList(tracked));
        for(DocumentBlock block:sources.get(0).getBlocks()){assertEquals("source_bound",context(block).path("status").asText());assertEquals("unknown",context(block).path("storyStatus").asText());assertEquals("unknown",context(block).path("sourceScopeExclusion").path("status").asText());}
        verify(tracked,times(1)).getParseCoverageJson();
    }
    @Test void ruleSourceReuseDoesNotSurviveAnotherCallOrMaskDuplicateBlocks(){
        Fixture f=multipleParts();SourceDocument tracked=spy(f.source);OerBusinessEvidence.ordinaryRuleSources("project",Collections.singletonList(tracked));
        clearInvocations(tracked);List<DocumentBlock> changed=VettingCorpus.blocks(f.source);changed.add(changed.get(1));tracked.setStructuredContentJson(JsonUtils.write(changed));tracked.setParseCoverageJson("{broken");
        List<VettingRuleEngine.Source> refreshed=OerBusinessEvidence.ordinaryRuleSources("project",Collections.singletonList(tracked));
        for(DocumentBlock block:refreshed.get(0).getBlocks())if(f.original.getId().equals(block.getId()))assertEquals("unknown",context(block).path("status").asText());
        assertEquals("unknown",context(refreshed.get(0).getBlocks().get(2)).path("storyStatus").asText());
        verify(tracked,times(1)).getTextContent();verify(tracked,times(3)).getStructuredContentJson();verify(tracked,times(1)).getParseCoverageJson();
    }
    @Test void rejectedCanonicalSourceDoesNotEagerlyParseBlocksOrCoverage(){
        for(String mutation:Arrays.asList("project","parse","hash")){Fixture f=new Fixture();if("project".equals(mutation))f.source.setProjectId("other");if("parse".equals(mutation))f.source.setParseStatus("FAILED");if("hash".equals(mutation))f.source.setTextContent("Changed source");SourceDocument tracked=spy(f.source);DocumentBlock target=new DocumentBlock();
            OerBusinessEvidence.bindRuleContext("project",tracked,f.chunk,f.part,target);assertEquals("unknown",context(target).path("status").asText());verify(tracked,never()).getParseCoverageJson();verify(tracked,times("hash".equals(mutation)?1:0)).getStructuredContentJson();}
    }
    @Test void canonicalMultiplePartsReuseDocumentReadsAndKeepEveryBoundBlockByte() throws Exception {
        OerBusinessEvidenceTest.Wire wire=canonicalParts();OerBusinessEvidence.Session session=wire.load();List<String> expected=new ArrayList<>();
        for(VettingCorpus.Chunk chunk:session.chunks())for(VettingCorpus.Part part:chunk.getParts()){
            DocumentBlock block=new DocumentBlock();block.setId(part.getBlockId());block.setLocation(part.getAnchor());block.setText(part.getText());block.setOriginalText(part.getText());block.setSource("source_reviewed_canonical_observation");
            OerBusinessEvidence.bindRuleContext("project",wire.document,chunk,part,block);expected.add(JsonUtils.write(block));
        }
        SourceDocument tracked=spy(wire.document);List<VettingRuleEngine.Source> sources=wire.service.ruleSources(session,Collections.singletonList(tracked));
        assertEquals(1,sources.size());assertEquals(expected.size(),sources.get(0).getBlocks().size());assertTrue(expected.size()>4);
        for(int i=0;i<expected.size();i++)assertEquals(expected.get(i),JsonUtils.write(sources.get(0).getBlocks().get(i)));
        verify(tracked,never()).getTextContent();verify(tracked,times(2)).getStructuredContentJson();verify(tracked,times(1)).getParseCoverageJson();
    }
    @Test void duplicateCapturedSourcesAndLaterSourceDriftCannotReuseCanonicalContext() throws Exception {
        OerBusinessEvidenceTest.Wire wire=canonicalParts();OerBusinessEvidence.Session session=wire.load();SourceDocument tracked=spy(wire.document);
        List<VettingRuleEngine.Source> duplicate=wire.service.ruleSources(session,Arrays.asList(tracked,tracked));
        for(DocumentBlock block:duplicate.get(0).getBlocks())assertEquals("unknown",context(block).path("status").asText());
        verify(tracked,never()).getStructuredContentJson();verify(tracked,never()).getParseCoverageJson();
        wire.service.ruleSources(session,Collections.singletonList(tracked));clearInvocations(tracked);tracked.setTextContent("Changed after the prior rule call");
        List<VettingRuleEngine.Source> changed=wire.service.ruleSources(session,Collections.singletonList(tracked));
        for(DocumentBlock block:changed.get(0).getBlocks())assertEquals("unknown",context(block).path("status").asText());
        verify(tracked,times(1)).getStructuredContentJson();verify(tracked,never()).getParseCoverageJson();
    }
    private OerBusinessEvidenceTest.Wire canonicalParts() throws Exception {
        OerBusinessEvidenceTest.Wire wire=new OerBusinessEvidenceTest.Wire(true);List<DocumentBlock> blocks=new ArrayList<>();
        for(JsonNode chunk:wire.snapshot.path("chunks"))for(JsonNode part:chunk.path("parts")){
            DocumentBlock block=new DocumentBlock();block.setId(part.path("blockId").asText());block.setLocation(part.path("anchor").asText());block.setText(part.path("text").asText());block.setOriginalText(block.getText());block.setKind("paragraph");block.setSourcePosition(part.path("sourcePosition").deepCopy());blocks.add(block);
        }
        wire.document.setStructuredContentJson(JsonUtils.write(blocks));wire.document.setTextContent(String.join("\n",blocks.stream().map(DocumentBlock::getEffectiveText).toArray(String[]::new)));wire.document.setParseStatus("PARSED");wire.document.setSourceSha256(wire.binding.getOriginalSourceSha256());wire.document.setReviewRole("tender");wire.document.setParseCoverageJson("{}");wire.binding.setJavaParsedSourceHash(VettingCorpus.sourceHash(wire.document));return wire;
    }
    private Fixture multipleParts(){
        Fixture f=scopeFixture("Sample");List<DocumentBlock> blocks=new ArrayList<>(VettingCorpus.blocks(f.source));ObjectNode coverage=(ObjectNode)JsonUtils.parse(f.source.getParseCoverageJson());
        for(int i=0;i<5;i++){DocumentBlock extra=JsonUtils.read(JsonUtils.write(f.original),DocumentBlock.class);extra.setId("extra-"+i);extra.setLocation("extra-anchor-"+i);((ObjectNode)extra.getSourcePosition()).put("nodePath","/{urn:word}document[1]/{urn:word}body[1]/{urn:word}p["+(i+3)+"]");blocks.add(extra);((ObjectNode)coverage.path("nativeDocxOutline").path("headings").get(0)).withArray("retainedBlockIds").add(extra.getId());}
        f.source.setStructuredContentJson(JsonUtils.write(blocks));f.source.setTextContent(String.join("\n",blocks.stream().map(DocumentBlock::getEffectiveText).toArray(String[]::new)));f.source.setParseCoverageJson(JsonUtils.write(coverage));return f;
    }
    private DocumentBlock isolatedBinding(SourceDocument source,DocumentBlock original){
        DocumentBlock target=JsonUtils.read(JsonUtils.write(original),DocumentBlock.class);VettingCorpus.Part part=new VettingCorpus.Part();part.setBlockId(original.getId());part.setAnchor(original.getLocation());part.setText(original.getEffectiveText());part.setStartOffset(0);part.setEndOffset(part.getText().length());
        ObjectNode payload=JsonUtils.mapper().createObjectNode(),raw=payload.withArray("parts").addObject();raw.put("blockId",part.getBlockId());raw.put("startOffset",0);raw.put("endOffset",part.getEndOffset());raw.put("text",part.getText());if(original.getSourcePosition()!=null)raw.set("sourcePosition",original.getSourcePosition().deepCopy());
        VettingCorpus.Chunk chunk=new VettingCorpus.Chunk();chunk.setDocumentId(String.valueOf(source.getId()));chunk.setCanonicalPayload(payload);EvidencePointer pointer=new EvidencePointer();pointer.setJavaParsedSourceHash(VettingCorpus.sourceHash(source));pointer.setOriginalSourceSha256(source.getSourceSha256());chunk.setCanonicalEvidence(pointer);
        OerBusinessEvidence.bindRuleContext("project",source,chunk,part,target);return target;
    }
}
